Index: web/greeting.mjs
===================================================================
--- web/greeting.mjs	
+++ web/greeting.mjs	
@@ -1,6 +1,6 @@
 export function greet(name) {
   if (!name || name.trim() === '') {
-    return '你好，';
+    return '你好，访客！';
   }
   return '你好，' + name.trim() + '！';
 }

