+++ web/greeting.test.mjs	
@@ -1,12 +1,12 @@
 import { greet } from './greeting.mjs';
 import assert from 'node:assert';

-assert.strictEqual(greet(undefined), '你好，');
-assert.strictEqual(greet(null), '你好，');
-assert.strictEqual(greet(''), '你好，');
-assert.strictEqual(greet('  '), '你好，');
+assert.strictEqual(greet(undefined), '你好，访客！');
+assert.strictEqual(greet(null), '你好，访客！');
+assert.strictEqual(greet(''), '你好，访客！');
+assert.strictEqual(greet('  '), '你好，访客！');
 assert.strictEqual(greet('小明'), '你好，小明！');
 assert.strictEqual(greet('  小红  '), '你好，小红！');
-assert.strictEqual(greet('  '), '你好，');
+assert.strictEqual(greet('  '), '你好，访客！');

 console.log('greeting.test.mjs — 全部通过');

