 <!DOCTYPE html>
 <html lang="zh-CN">
 <head>
 <meta charset="UTF-8">
 <meta name="viewport" content="width=device-width, initial-scale=1.0">
 <title>WorkBench 新网页</title>
 <style>
   * { margin: 0; padding: 0; box-sizing: border-box; }
   body { font-family: system-ui, sans-serif; display: flex; justify-content: center;
          align-items: center; min-height: 100vh; background: #f5f5f5; }
   .card { background: #fff; padding: 2rem 2.5rem; border-radius: 12px;
           box-shadow: 0 2px 12px rgba(0,0,0,0.1); text-align: center; }
   h1 { margin-bottom: 1.2rem; font-size: 1.4rem; color: #333; }
   label { display: block; margin-bottom: 0.4rem; font-size: 0.95rem; color: #555; }
   input { padding: 0.5rem 0.8rem; border: 1px solid #ccc; border-radius: 6px;
           font-size: 1rem; width: 100%; margin-bottom: 1rem; }
   button { padding: 0.5rem 1.6rem; border: none; border-radius: 6px;
            background: #4a90d9; color: #fff; font-size: 1rem; cursor: pointer; }
   button:hover { background: #357ab8; }
   #result { margin-top: 1.2rem; font-size: 1.15rem; color: #333; min-height: 1.6rem; }
 </style>
 </head>
 <body>
 <div class="card">
   <h1>WorkBench 新网页</h1>
   <label for="name">姓名</label>
   <input id="name" type="text" placeholder="请输入姓名">
   <button id="btn">问候</button>
   <div id="result"></div>
 </div>
 <script type="module">
   function greet(name) {
     if (!name || name.trim() === '') {
-      return '你好，';
+      return '你好，访客！';
     }
     return '你好，' + name.trim() + '！';
   }

   document.getElementById('btn').addEventListener('click', () => {
     const n = document.getElementById('name').value;
     document.getElementById('result').textContent = greet(n);
   });
 </script>
 </body>
 </html>

